    .optional(),
});

export const submissionResponseSchema = z.object({
  data: submissionSchema,
});

export const correctionSchema = z.object({
  eventId: submissionEventIdSchema,
  fixtureId: apiIdentifierSchema,
  revision: z.number().int().positive(),
});

export const correctionResponseSchema = z.object({
  data: correctionSchema,
});

export type SubmissionRequest = z.infer<typeof submissionRequestSchema>;
export type SubmissionEvent = z.infer<typeof submissionEventSchema>;
export type SubmissionResponse = z.infer<typeof submissionResponseSchema>;
export type SubmissionSourceFile = NonNullable<z.infer<typeof submissionSchema>['sourceFile']>;
export type CorrectionRequest = z.infer<typeof correctionRequestSchema>;
export type CorrectionResponse = z.infer<typeof correctionResponseSchema>;
import type {
  CorrectionRequest,
  CorrectionResponse,
  SubmissionRequest,
  SubmissionResponse,
  SubmissionSourceFile,
} from '@sport-analytics/contracts';

import { canSubmitToCompetition } from '../../middleware/require-authorization';
import type { ApplicationAccount } from '../accounts/account';
import { SubmissionForbiddenError, SubmissionValidationError } from './submission.errors';
import { createSubmissionRepository, type SubmissionRepository } from './submission.repository';

export interface SubmissionService {
  submit(
    account: ApplicationAccount,
    submission: SubmissionRequest,
    sourceFile?: SubmissionSourceFile,
  ): Promise<SubmissionResponse>;
  correct(
    account: ApplicationAccount,
    eventId: string,
    correction: CorrectionRequest,
  ): Promise<CorrectionResponse>;
}

export function createSubmissionService(
  repository: SubmissionRepository = createSubmissionRepository(),
): SubmissionService {
  return {
    async submit(account, submission, sourceFile) {
      const fixture = await repository.findFixtureScope(submission.fixtureId);
      if (!fixture) {
        throw new SubmissionValidationError('The submission references an unavailable fixture.', [
          {
            code: 'FIXTURE_NOT_FOUND',
            message: 'The fixture does not exist.',
            field: 'fixtureId',
          },
        ]);
      }

      if (!fixture.competitionId || !canSubmitToCompetition(account, fixture.competitionId)) {
        throw new SubmissionForbiddenError();
      }

      // The dismissal vocabulary is held in the dismissal_kind lookup table, not
      // enumerated in the contract, because the set is open. Resolving it here
      // rather than relying on the foreign key means an unrecognised kind is
      // rejected with the field and the value that caused it, instead of
      // surfacing as an unexplained server error.
      const submittedWickets = submission.events.flatMap((event, eventIndex) =>
        event.wickets.map((wicket) => ({ eventIndex, kind: wicket.kind })),
      );

      if (submittedWickets.length > 0) {
        const recognisedKinds = await repository.findDismissalKinds();
        const unrecognised = submittedWickets.filter((wicket) => !recognisedKinds.has(wicket.kind));

        if (unrecognised.length > 0) {
          throw new SubmissionValidationError(
            'The submission references a dismissal kind the platform does not recognise.',
            unrecognised.map((wicket) => ({
              code: 'UNKNOWN_DISMISSAL_KIND',
              message: `"${wicket.kind}" is not a recognised dismissal kind.`,
              field: 'wickets.kind',
              eventIndex: wicket.eventIndex,
            })),
          );
        }
      }

      const acceptedSubmission = await repository.storeAcceptedSubmission(
        submission,
        account.accountId,
        sourceFile,
      );

      return {
        data: acceptedSubmission,
      };
    },

    async correct(account, eventId, correction) {
      const target = await repository.findCorrectionTarget(eventId);
      if (!target || target.fixtureId !== correction.fixtureId) {
        throw new SubmissionValidationError('The correction references an unavailable event.', [
          {
            code: 'EVENT_NOT_FOUND',
            message: 'The source event is not an accepted, correctable event for this fixture.',
            field: 'eventId',
          },
        ]);
      }

      if (!target.competitionId || !canSubmitToCompetition(account, target.competitionId)) {
        throw new SubmissionForbiddenError();
      }

      const submittedWickets = correction.event.wickets.map((wicket) => wicket.kind);
      if (submittedWickets.length > 0) {
        const recognisedKinds = await repository.findDismissalKinds();
        const unrecognised = submittedWickets.filter((kind) => !recognisedKinds.has(kind));
        if (unrecognised.length > 0) {
          throw new SubmissionValidationError(
            'The correction references a dismissal kind the platform does not recognise.',
            unrecognised.map((kind) => ({
              code: 'UNKNOWN_DISMISSAL_KIND',
              message: `"${kind}" is not a recognised dismissal kind.`,
              field: 'event.wickets.kind',
            })),
          );
        }
      }

      return {
        data: await repository.storeAcceptedCorrection(eventId, correction, account.accountId),
      };
    },
  };
}
import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireSubmitter } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import {
  createCorrectionController,
  createSubmissionController,
  createSubmissionUploadController,
} from './submission.controller';
import { createSubmissionRateLimit } from './submission-rate-limit';
import type { SubmissionService } from './submission.service';
import { createSubmissionUploadMiddleware } from './submission-upload';

export function createSubmissionRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: SubmissionService,
): Router {
  const router = Router();

  router.post(
    '/submissions',
    requireAuthentication(verifyAccessToken, synchronizeAccount),
    requireSubmitter(),
    createSubmissionRateLimit(),
    createSubmissionController(service),
  );

  router.post(
    '/submissions/uploads',
    requireAuthentication(verifyAccessToken, synchronizeAccount),
    requireSubmitter(),
    createSubmissionRateLimit(),
    createSubmissionUploadMiddleware(),
    createSubmissionUploadController(service),
  );

  router.put(
    '/submissions/events/:eventId',
    requireAuthentication(verifyAccessToken, synchronizeAccount),
    requireSubmitter(),
    createSubmissionRateLimit(),
    createCorrectionController(service),
  );

  return router;
}
import {
  correctionRequestSchema,
  submissionEventIdSchema,
  submissionRequestSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import { rejectAuthorization } from '../../middleware/authorization-response';
import type { ApplicationAccount } from '../accounts/account';
import {
  SubmissionConflictError,
  SubmissionForbiddenError,
  SubmissionValidationError,
} from './submission.errors';
import type { SubmissionService } from './submission.service';
import { parseSubmissionUpload } from './submission-upload';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Submission controller requires an authenticated application account');
  }

  return account;
}

export function createSubmissionController(service: SubmissionService): RequestHandler {
  return (request, response, next) => {
    const parsed = submissionRequestSchema.safeParse(request.body);

    if (!parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submission is invalid.',
          details: parsed.error.issues.map((issue) => {
            const eventPathIndex = issue.path[0] === 'events' ? issue.path[1] : undefined;
            return {
              code: 'INVALID_FIELD',
              message: issue.message,
              ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
              ...(typeof eventPathIndex === 'number' ? { eventIndex: eventPathIndex } : {}),
            };
          }),
        },
      });
      return;
    }

    let account: ApplicationAccount;
    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .submit(account, parsed.data)
      .then((submission) => {
        response.status(201).json(submission);
      })
      .catch((error: unknown) => {
        if (error instanceof SubmissionForbiddenError) {
          rejectAuthorization(response);
          return;
        }

        if (error instanceof SubmissionValidationError) {
          response.status(422).json({
            error: {
              code: 'VALIDATION_FAILED',
              message: error.message,
              details: error.details,
            },
          });
          return;
        }

        if (error instanceof SubmissionConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        next(error);
      });
  };
}

function rejectInvalidSubmission(
  response: Response,
  message: string,
  issues: { path: (string | number)[]; message: string }[],
): void {
  response.status(422).json({
    error: {
      code: 'VALIDATION_FAILED',
      message,
      details: issues.map((issue) => {
        const eventPathIndex = issue.path[0] === 'events' ? issue.path[1] : undefined;
        return {
          code: 'INVALID_FIELD',
          message: issue.message,
          ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
          ...(typeof eventPathIndex === 'number' ? { eventIndex: eventPathIndex } : {}),
        };
      }),
    },
  });
}

export function createSubmissionUploadController(service: SubmissionService): RequestHandler {
  return (request, response, next) => {
    if (!request.file) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The uploaded submission file is invalid.',
          details: [
            { code: 'INVALID_FILE', field: 'file', message: 'Attach one submission file.' },
          ],
        },
      });
      return;
    }

    let upload;
    try {
      upload = parseSubmissionUpload(request.file);
    } catch (error) {
      if (error instanceof SubmissionValidationError) {
        response.status(422).json({
          error: { code: 'VALIDATION_FAILED', message: error.message, details: error.details },
        });
        return;
      }
      next(error);
      return;
    }

    const parsed = submissionRequestSchema.safeParse(upload.submission);
    if (!parsed.success) {
      rejectInvalidSubmission(response, 'The uploaded submission is invalid.', parsed.error.issues);
      return;
    }

    let account: ApplicationAccount;
    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .submit(account, parsed.data, upload.sourceFile)
      .then((submission) => response.status(201).json(submission))
      .catch((error: unknown) => {
        if (error instanceof SubmissionForbiddenError) {
          rejectAuthorization(response);
          return;
        }
        if (error instanceof SubmissionValidationError) {
          response.status(422).json({
            error: { code: 'VALIDATION_FAILED', message: error.message, details: error.details },
          });
          return;
        }
        if (error instanceof SubmissionConflictError) {
          response.status(409).json({ error: { code: error.code, message: error.message } });
          return;
        }
        next(error);
      });
  };
}

export function createCorrectionController(service: SubmissionService): RequestHandler {
  return (request, response, next) => {
    const eventId = submissionEventIdSchema.safeParse(request.params.eventId);
    const parsed = correctionRequestSchema.safeParse(request.body);

    if (!eventId.success || !parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The correction is invalid.',
          details: [
            ...(!eventId.success
              ? eventId.error.issues.map((issue) => ({
                  code: 'INVALID_FIELD',
                  message: issue.message,
                  field: 'eventId',
                }))
              : []),
            ...(!parsed.success
              ? parsed.error.issues.map((issue) => ({
                  code: 'INVALID_FIELD',
                  message: issue.message,
                  ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
                }))
              : []),
          ],
        },
      });
      return;
    }

    let account: ApplicationAccount;
    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .correct(account, eventId.data, parsed.data)
      .then((correction) => response.status(200).json(correction))
      .catch((error: unknown) => {
        if (error instanceof SubmissionForbiddenError) {
          rejectAuthorization(response);
          return;
        }

        if (error instanceof SubmissionValidationError) {
          response.status(422).json({
            error: {
              code: 'VALIDATION_FAILED',
              message: error.message,
              details: error.details,
            },
          });
          return;
        }

        if (error instanceof SubmissionConflictError) {
          response.status(409).json({
            error: { code: error.code, message: error.message },
          });
          return;
        }

        next(error);
      });
  };
}
import type { SubmissionSourceFile } from '@sport-analytics/contracts';
import type { Express, RequestHandler } from 'express';
import multer from 'multer';
import { basename } from 'node:path';

import { SubmissionValidationError } from './submission.errors';

const MAX_SUBMISSION_UPLOAD_BYTES = 1_000_000;
const SUBMISSION_UPLOAD_FIELD = 'file';

const csvHeaders = [
  'fixtureId',
  'schemaVersion',
  'eventId',
  'inningsId',
  'sequenceNumber',
  'overNumber',
  'positionInOver',
  'ballNumber',
  'strikerId',
  'nonStrikerId',
  'bowlerId',
  'runsOffBat',
  'runsExtras',
  'runsTotal',
  'runsNonBoundary',
  'extraWides',
  'extraNoBalls',
  'extraByes',
  'extraLegByes',
  'extraPenalty',
  'wickets',
] as const;

type CsvHeader = (typeof csvHeaders)[number];
type CsvRow = Record<CsvHeader, string>;

export interface ParsedSubmissionUpload {
  submission: unknown;
  sourceFile: SubmissionSourceFile;
}

function invalidFile(message: string, field = SUBMISSION_UPLOAD_FIELD): SubmissionValidationError {
  return new SubmissionValidationError('The uploaded submission file is invalid.', [
    { code: 'INVALID_FILE', message, field },
  ]);
}

function normaliseMediaType(file: Express.Multer.File): SubmissionSourceFile['mediaType'] {
  const name = file.originalname.toLocaleLowerCase();
  const mediaType = file.mimetype.toLocaleLowerCase();

  if (name.endsWith('.json') && (mediaType === 'application/json' || mediaType === 'text/json')) {
    return 'application/json';
  }

  if (name.endsWith('.csv') && (mediaType === 'text/csv' || mediaType === 'application/csv')) {
    return 'text/csv';
  }

  throw invalidFile('Upload a .json application/json file or a .csv text/csv file.');
}

function parseCsv(content: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let value = '';
  let quoted = false;

  for (let index = 0; index < content.length; index += 1) {
    const character = content[index]!;

    if (quoted) {
      if (character === '"' && content[index + 1] === '"') {
        value += '"';
        index += 1;
      } else if (character === '"') {
        quoted = false;
      } else {
        value += character;
      }
      continue;
    }

    if (character === '"') {
      quoted = true;
    } else if (character === ',') {
      row.push(value);
      value = '';
    } else if (character === '\n') {
      row.push(value.replace(/\r$/, ''));
      rows.push(row);
      row = [];
      value = '';
    } else {
      value += character;
    }
  }

  if (quoted) {
    throw invalidFile('The CSV file contains an unterminated quoted value.');
  }

  if (value.length > 0 || row.length > 0) {
    row.push(value.replace(/\r$/, ''));
    rows.push(row);
  }

  return rows;
}

function csvRows(content: string): CsvRow[] {
  const rows = parseCsv(content);
  const [header, ...dataRows] = rows;

  if (
    !header ||
    header.length !== csvHeaders.length ||
    !csvHeaders.every((value, index) => header[index] === value)
  ) {
    throw invalidFile(`The CSV header must exactly contain: ${csvHeaders.join(', ')}.`);
  }

  if (dataRows.length === 0) {
    throw invalidFile('The CSV file must contain at least one event row.');
  }

  return dataRows.map((row, eventIndex) => {
    if (row.length !== csvHeaders.length) {
      throw new SubmissionValidationError('The uploaded submission file is invalid.', [
        {
          code: 'INVALID_FILE_ROW',
          message: `CSV row ${eventIndex + 2} has ${row.length} columns; ${csvHeaders.length} are required.`,
          field: 'file',
          eventIndex,
        },
      ]);
    }

    return Object.fromEntries(
      csvHeaders.map((headerName, index) => [headerName, row[index]!]),
    ) as CsvRow;
  });
}

function numberValue(value: string): number | undefined | string {
  if (value.trim() === '') {
    return undefined;
  }

  return /^-?\d+(?:\.\d+)?$/.test(value) ? Number(value) : value;
}

function booleanValue(value: string): boolean | undefined | string {
  if (value.trim() === '') {
    return undefined;
  }

  if (value === 'true') {
    return true;
  }
  if (value === 'false') {
    return false;
  }
  return value;
}

function optionalExtras(row: CsvRow) {
  return {
    ...(row.extraWides.trim() !== '' ? { wides: numberValue(row.extraWides) } : {}),
    ...(row.extraNoBalls.trim() !== '' ? { noBalls: numberValue(row.extraNoBalls) } : {}),
    ...(row.extraByes.trim() !== '' ? { byes: numberValue(row.extraByes) } : {}),
    ...(row.extraLegByes.trim() !== '' ? { legByes: numberValue(row.extraLegByes) } : {}),
    ...(row.extraPenalty.trim() !== '' ? { penalty: numberValue(row.extraPenalty) } : {}),
  };
}

function parseWickets(value: string): unknown {
  if (value.trim() === '') {
    return [];
  }

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function normaliseCsv(content: string): unknown {
  const rows = csvRows(content);
  const first = rows[0]!;

  const inconsistentRows = rows.flatMap((row, eventIndex) => [
    ...(row.fixtureId === first.fixtureId
      ? []
      : [
          {
            code: 'INVALID_FILE_ROW',
            message: 'Every CSV row must use the same fixtureId.',
            field: 'fixtureId',
            eventIndex,
          },
        ]),
    ...(row.schemaVersion === first.schemaVersion
      ? []
      : [
          {
            code: 'INVALID_FILE_ROW',
            message: 'Every CSV row must use the same schemaVersion.',
            field: 'schemaVersion',
            eventIndex,
          },
        ]),
  ]);

  if (inconsistentRows.length > 0) {
    throw new SubmissionValidationError(
      'The uploaded submission file is invalid.',
      inconsistentRows,
    );
  }

  return {
    fixtureId: first.fixtureId,
    schemaVersion: first.schemaVersion,
    events: rows.map((row) => ({
      eventId: row.eventId,
      inningsId: row.inningsId,
      sequenceNumber: numberValue(row.sequenceNumber),
      overNumber: numberValue(row.overNumber),
      positionInOver: numberValue(row.positionInOver),
      ballNumber: row.ballNumber,
      strikerId: row.strikerId,
      nonStrikerId: row.nonStrikerId,
      bowlerId: row.bowlerId,
      runs: {
        offBat: numberValue(row.runsOffBat),
        extras: numberValue(row.runsExtras),
        total: numberValue(row.runsTotal),
        ...(booleanValue(row.runsNonBoundary) !== undefined
          ? { nonBoundary: booleanValue(row.runsNonBoundary) }
          : {}),
      },
      extras: optionalExtras(row),
      wickets: parseWickets(row.wickets),
    })),
  };
}

export function parseSubmissionUpload(file: Express.Multer.File): ParsedSubmissionUpload {
  if (file.size === 0) {
    throw invalidFile('The uploaded file is empty.');
  }

  const fileName = basename(file.originalname);
  if (!fileName || fileName.length > 255) {
    throw invalidFile('The uploaded filename must be between 1 and 255 characters.');
  }

  const mediaType = normaliseMediaType(file);
  const sourceFile = {
    fileName,
    mediaType,
    sizeBytes: file.size,
  } as const;
  const content = file.buffer.toString('utf8');

  if (mediaType === 'application/json') {
    try {
      return { submission: JSON.parse(content), sourceFile };
    } catch {
      throw invalidFile('The uploaded JSON file is not valid JSON.');
    }
  }

  return { submission: normaliseCsv(content), sourceFile };
}

export function createSubmissionUploadMiddleware(): RequestHandler {
  const upload = multer({
    storage: multer.memoryStorage(),
    limits: { files: 1, fileSize: MAX_SUBMISSION_UPLOAD_BYTES },
  }).single(SUBMISSION_UPLOAD_FIELD);

  return (request, response, next) => {
    upload(request, response, (error: unknown) => {
      if (error instanceof multer.MulterError && error.code === 'LIMIT_FILE_SIZE') {
        response.status(413).json({
          error: {
            code: 'PAYLOAD_TOO_LARGE',
            message: 'The uploaded file exceeds the 1 MB size limit.',
          },
        });
        return;
      }

      if (error instanceof multer.MulterError) {
        response.status(422).json({
          error: {
            code: 'VALIDATION_FAILED',
            message: 'The uploaded submission file is invalid.',
            details: [{ code: 'INVALID_FILE', field: 'file', message: error.message }],
          },
        });
        return;
      }

      next(error);
    });
  };
}

