import type {
  FixtureStatistic,
  FixtureStatistics,
  FixtureStatisticsQuery,
} from '@sport-analytics/contracts';

import { deriveFixtureStatistics } from './fixture-statistics.derivation';
import type { FixtureStatisticsSource } from './fixture-statistics.model';
import { loadFixtureStatisticsSource } from './fixture-statistics.repository';

export type LoadFixtureStatisticsSource = (
  fixtureId: string,
) => Promise<FixtureStatisticsSource | null>;

export interface FixtureStatisticsService {
  getFixtureStatistics(
    fixtureId: string,
    query: FixtureStatisticsQuery,
  ): Promise<FixtureStatistics | null>;
  getFixtureStatistic(
    fixtureId: string,
    statisticId: string,
    query: FixtureStatisticsQuery,
  ): Promise<FixtureStatistic | null>;
}

const databaseIdPattern = /^\d+$/;

export function createFixtureStatisticsService(
  loadSource: LoadFixtureStatisticsSource = loadFixtureStatisticsSource,
): FixtureStatisticsService {
  async function derive(
    fixtureId: string,
    query: FixtureStatisticsQuery,
  ): Promise<FixtureStatistics | null> {
    if (!databaseIdPattern.test(fixtureId)) {
      return null;
    }

    const source = await loadSource(fixtureId);
    if (!source) {
      return null;
    }

    return deriveFixtureStatistics(source, {
      includeContributors: query.includeContributors,
    });
  }

  return {
    getFixtureStatistics: derive,

    async getFixtureStatistic(fixtureId, statisticId, query) {
      const fixtureStatistics = await derive(fixtureId, query);
      if (!fixtureStatistics) {
        return null;
      }

      return (
        fixtureStatistics.statistics.find((statistic) => statistic.statisticId === statisticId) ??
        null
      );
    },
  };
}
import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';
import type {
  FixtureStatisticsEventSource,
  FixtureStatisticsInningsSource,
  FixtureStatisticsSource,
} from './fixture-statistics.model';

interface FixtureInningsRow {
  fixtureId: string;
  ballsPerOver: number;
  missingFields: string[];
  outcome: FixtureStatisticsSource['outcome'];
  winnerCompetitorId: string | null;
  winnerCompetitorName: string | null;
  eliminatorCompetitorId: string | null;
  eliminatorCompetitorName: string | null;
  outcomeByRuns: number | null;
  outcomeByWickets: number | null;
  outcomeMethod: string | null;
  decidedByBowlOut: boolean;
  inningsId: string | null;
  inningsOrdinal: number | null;
  battingCompetitorId: string | null;
  battingCompetitorName: string | null;
  penaltyPre: number | null;
  penaltyPost: number | null;
}

type DeliveryRow = FixtureStatisticsEventSource;

export async function loadFixtureStatisticsSource(
  fixtureId: string,
  executor: QueryExecutor = getDatabasePool(),
): Promise<FixtureStatisticsSource | null> {
  const fixtureResult = await executeQuery<FixtureInningsRow>(
    executor,
    `
    SELECT
      f.fixture_id::text AS "fixtureId",
      f.balls_per_over AS "ballsPerOver",
      f.missing_fields AS "missingFields",
      f.outcome::text AS outcome,
      f.winner_id::text AS "winnerCompetitorId",
      winner_team.name AS "winnerCompetitorName",
      f.eliminator_id::text AS "eliminatorCompetitorId",
      eliminator_team.name AS "eliminatorCompetitorName",
      f.outcome_by_runs AS "outcomeByRuns",
      f.outcome_by_wickets AS "outcomeByWickets",
      f.outcome_method AS "outcomeMethod",
      f.decided_by_bowl_out AS "decidedByBowlOut",
      i.innings_id::text AS "inningsId",
      i.ordinal AS "inningsOrdinal",
      i.batting_team_id::text AS "battingCompetitorId",
      batting_team.name AS "battingCompetitorName",
      i.penalty_pre AS "penaltyPre",
      i.penalty_post AS "penaltyPost"
    FROM fixture f
    JOIN submission publication
      ON publication.submission_id = f.first_seen_in
     AND publication.status = 'accepted'
    LEFT JOIN team winner_team
      ON winner_team.team_id = f.winner_id
    LEFT JOIN team eliminator_team
      ON eliminator_team.team_id = f.eliminator_id
    LEFT JOIN innings i
      ON i.fixture_id = f.fixture_id
     AND i.is_super_over = false
    LEFT JOIN team batting_team
      ON batting_team.team_id = i.batting_team_id
    WHERE f.fixture_id = $1::bigint
    ORDER BY i.ordinal ASC
  `,
    [fixtureId],
  );

  const fixtureRow = fixtureResult.rows[0];
  if (!fixtureRow) {
    return null;
  }

  const innings: FixtureStatisticsInningsSource[] = fixtureResult.rows.flatMap((row) => {
    if (
      row.inningsId === null ||
      row.inningsOrdinal === null ||
      row.battingCompetitorId === null ||
      row.battingCompetitorName === null
    ) {
      return [];
    }

    return [
      {
        inningsId: row.inningsId,
        ordinal: row.inningsOrdinal,
        battingCompetitorId: row.battingCompetitorId,
        battingCompetitorName: row.battingCompetitorName,
        penaltyPre: row.penaltyPre,
        penaltyPost: row.penaltyPost,
      },
    ];
  });

  const standardInningsIds = innings.map((inningsRecord) => inningsRecord.inningsId);

  const deliveryResult = await executeQuery<DeliveryRow>(
    executor,
    `
    WITH accepted_delivery AS (
      SELECT DISTINCT ON (d.innings_id, d.over_number, d.position_in_over)
        d.*
      FROM delivery_current d
      JOIN submission source_submission
        ON source_submission.submission_id = d.submission_id
       AND source_submission.status = 'accepted'
      WHERE d.innings_id = ANY($1::bigint[])
      ORDER BY
        d.innings_id ASC,
        d.over_number ASC,
        d.position_in_over ASC,
        d.revision DESC,
        d.delivery_id DESC
    )
    SELECT
      d.delivery_id::text AS "deliveryId",
      i.innings_id::text AS "inningsId",
      i.ordinal AS "inningsOrdinal",
      d.innings_sequence AS "inningsSequence",
      i.batting_team_id::text AS "battingCompetitorId",
      batting_team.name AS "battingCompetitorName",
      bowling_team.competitor_id AS "bowlingCompetitorId",
      bowling_team.competitor_name AS "bowlingCompetitorName",
      d.striker_id::text AS "strikerId",
      striker_person.display_name AS "strikerName",
      d.bowler_id::text AS "bowlerId",
      bowler_person.display_name AS "bowlerName",
      d.runs_off_bat AS "runsOffBat",
      d.runs_extras AS "runsExtras",
      d.runs_total AS "runsTotal",
      d.non_boundary AS "nonBoundary",
      d.extra_wides AS "extraWides",
      d.extra_noballs AS "extraNoBalls",
      d.extra_byes AS "extraByes",
      d.extra_legbyes AS "extraLegByes",
      d.extra_penalty AS "extraPenalty",
      (
        SELECT COUNT(*)::int
        FROM delivery_wicket dw
        JOIN dismissal_kind dk ON dk.code = dw.kind
        WHERE dw.delivery_id = d.delivery_id
          AND dk.credits_bowler = true
      ) AS "creditedWickets"
    FROM accepted_delivery d
    JOIN innings i
      ON i.innings_id = d.innings_id
    JOIN team batting_team
      ON batting_team.team_id = i.batting_team_id
    JOIN person striker_person
      ON striker_person.person_id = d.striker_id
    JOIN person bowler_person
      ON bowler_person.person_id = d.bowler_id
    LEFT JOIN LATERAL (
      SELECT
        ft.team_id::text AS competitor_id,
        t.name AS competitor_name
      FROM fixture_team ft
      JOIN team t
        ON t.team_id = ft.team_id
      WHERE ft.fixture_id = i.fixture_id
        AND ft.team_id <> i.batting_team_id
      ORDER BY ft.ordinal ASC
      LIMIT 1
    ) bowling_team ON true
    ORDER BY i.ordinal ASC, d.innings_sequence ASC, d.delivery_id ASC
  `,
    [standardInningsIds],
  );

  return {
    fixtureId: fixtureRow.fixtureId,
    ballsPerOver: fixtureRow.ballsPerOver,
    missingFields: fixtureRow.missingFields,
    outcome: fixtureRow.outcome,
    winnerCompetitorId: fixtureRow.winnerCompetitorId,
    winnerCompetitorName: fixtureRow.winnerCompetitorName,
    eliminatorCompetitorId: fixtureRow.eliminatorCompetitorId,
    eliminatorCompetitorName: fixtureRow.eliminatorCompetitorName,
    outcomeByRuns: fixtureRow.outcomeByRuns,
    outcomeByWickets: fixtureRow.outcomeByWickets,
    outcomeMethod: fixtureRow.outcomeMethod,
    decidedByBowlOut: fixtureRow.decidedByBowlOut,
    innings,
    events: deliveryResult.rows,
  };
}
import { createHash } from 'node:crypto';
import type {
  FixtureOutcome,
  FixtureStatistic,
  FixtureStatistics,
  FixtureStatisticsWarning,
  ParticipantFixtureStatistic,
  StatisticContributingEvent,
} from '@sport-analytics/contracts';

import type {
  FixtureStatisticsEventSource,
  FixtureStatisticsSource,
} from './fixture-statistics.model';
import { calculateRate, formatOvers } from './fixture-statistics.metrics';

interface BattingAccumulator {
  runsScored: number;
  ballsFaced: number;
  fours: number;
  sixes: number;
}

interface BowlingAccumulator {
  runsConceded: number;
  legalBallsBowled: number;
  wicketsTaken: number;
}

interface ParticipantAccumulator {
  participantId: string;
  participantName: string;
  competitorIds: Set<string>;
  competitorNames: Map<string, string>;
  batting: BattingAccumulator | null;
  bowling: BowlingAccumulator | null;
  events: FixtureStatisticsEventSource[];
  eventIds: Set<string>;
}

export interface DeriveFixtureStatisticsOptions {
  includeContributors?: boolean;
}

function compareDatabaseIds(left: string, right: string): number {
  if (left.length !== right.length) {
    return left.length - right.length;
  }

  return left.localeCompare(right);
}

function statisticId(fixtureId: string, scope: string, scopeId: string): string {
  const digest = createHash('sha256')
    .update(`${fixtureId}\u0000${scope}\u0000${scopeId}`)
    .digest('base64url');

  return `stat_${digest}`;
}

function mapContributingEvent(
  fixtureId: string,
  event: FixtureStatisticsEventSource,
): StatisticContributingEvent {
  return {
    eventId: event.deliveryId,
    fixtureId,
    inningsId: event.inningsId,
    inningsOrdinal: event.inningsOrdinal,
    sequenceNumber: event.inningsSequence,
    strikerParticipantId: event.strikerId,
    strikerParticipantName: event.strikerName,
    bowlerParticipantId: event.bowlerId,
    bowlerParticipantName: event.bowlerName,
    runs: {
      offBat: event.runsOffBat,
      extras: event.runsExtras,
      total: event.runsTotal,
    },
    extras: {
      wides: event.extraWides,
      noBalls: event.extraNoBalls,
      byes: event.extraByes,
      legByes: event.extraLegByes,
      penalty: event.extraPenalty,
    },
    nonBoundary: event.nonBoundary,
    bowlerWickets: event.creditedWickets,
  };
}

function mapOutcome(source: FixtureStatisticsSource): FixtureOutcome {
  const margin =
    source.outcomeByRuns !== null
      ? {
          type: 'runs' as const,
          value: source.outcomeByRuns,
        }
      : source.outcomeByWickets !== null
        ? {
            type: 'wickets' as const,
            value: source.outcomeByWickets,
          }
        : null;

  return {
    kind: source.outcome === 'no result' ? 'no_result' : source.outcome,
    winnerCompetitorId: source.winnerCompetitorId,
    winnerCompetitorName: source.winnerCompetitorName,
    eliminatorCompetitorId: source.eliminatorCompetitorId,
    eliminatorCompetitorName: source.eliminatorCompetitorName,
    margin,
    method: source.outcomeMethod,
    decidedByBowlOut: source.decidedByBowlOut,
  };
}

function participantAccumulator(
  participants: Map<string, ParticipantAccumulator>,
  participantId: string,
  participantName: string,
): ParticipantAccumulator {
  const existing = participants.get(participantId);
  if (existing) {
    return existing;
  }

  const created: ParticipantAccumulator = {
    participantId,
    participantName,
    competitorIds: new Set<string>(),
    competitorNames: new Map<string, string>(),
    batting: null,
    bowling: null,
    events: [],
    eventIds: new Set<string>(),
  };

  participants.set(participantId, created);
  return created;
}

function addParticipantEvent(
  participant: ParticipantAccumulator,
  event: FixtureStatisticsEventSource,
): void {
  if (participant.eventIds.has(event.deliveryId)) {
    return;
  }

  participant.eventIds.add(event.deliveryId);
  participant.events.push(event);
}

export function deriveFixtureStatistics(
  source: FixtureStatisticsSource,
  options: DeriveFixtureStatisticsOptions = {},
): FixtureStatistics {
  const includeContributors = options.includeContributors ?? false;
  const warnings: FixtureStatisticsWarning[] = [];
  const orderedInnings = [...source.innings].sort((left, right) => left.ordinal - right.ordinal);
  const orderedEvents = [...source.events].sort(
    (left, right) =>
      left.inningsOrdinal - right.inningsOrdinal ||
      left.inningsSequence - right.inningsSequence ||
      compareDatabaseIds(left.deliveryId, right.deliveryId),
  );

  if (source.missingFields.length > 0) {
    warnings.push({
      code: 'SOURCE_DATA_INCOMPLETE',
      message: 'The accepted source identifies fields that were unavailable.',
      fields: [...source.missingFields].sort(),
    });
  }

  if (orderedInnings.length === 0) {
    warnings.push({
      code: 'NO_STANDARD_INNINGS',
      message: 'No non-super-over innings are available for derivation.',
    });
  }

  if (orderedEvents.length === 0) {
    warnings.push({
      code: 'NO_ACCEPTED_EVENTS',
      message: 'No accepted delivery events are available for derivation.',
    });
  }

  const statistics: FixtureStatistic[] = [];
  const participants = new Map<string, ParticipantAccumulator>();

  for (const innings of orderedInnings) {
    const events = orderedEvents.filter((event) => event.inningsId === innings.inningsId);
    if (events.length === 0) {
      warnings.push({
        code: 'INNINGS_WITHOUT_ACCEPTED_EVENTS',
        message: 'This innings has no accepted delivery events.',
        inningsId: innings.inningsId,
      });
    }

    const deliveryRuns = events.reduce((total, event) => total + event.runsTotal, 0);
    const penaltyRuns = (innings.penaltyPre ?? 0) + (innings.penaltyPost ?? 0);

    statistics.push({
      statisticId: statisticId(source.fixtureId, 'innings', innings.inningsId),
      fixtureId: source.fixtureId,
      scope: 'innings',
      statisticCode: 'team_total',
      inningsId: innings.inningsId,
      inningsOrdinal: innings.ordinal,
      competitorId: innings.battingCompetitorId,
      competitorName: innings.battingCompetitorName,
      sourceEventCount: events.length,
      metrics: {
        deliveryRuns,
        penaltyRuns,
        totalRuns: deliveryRuns + penaltyRuns,
      },
      ...(includeContributors
        ? {
            contributingEvents: events.map((event) =>
              mapContributingEvent(source.fixtureId, event),
            ),
          }
        : {}),
    });
  }

  for (const event of orderedEvents) {
    const batter = participantAccumulator(participants, event.strikerId, event.strikerName);
    batter.competitorIds.add(event.battingCompetitorId);
    batter.competitorNames.set(event.battingCompetitorId, event.battingCompetitorName);
    batter.batting ??= {
      runsScored: 0,
      ballsFaced: 0,
      fours: 0,
      sixes: 0,
    };
    batter.batting.runsScored += event.runsOffBat;
    if (event.extraWides === null) {
      batter.batting.ballsFaced += 1;
    }
    if (!event.nonBoundary && event.runsOffBat === 4) {
      batter.batting.fours += 1;
    }
    if (!event.nonBoundary && event.runsOffBat === 6) {
      batter.batting.sixes += 1;
    }
    addParticipantEvent(batter, event);

    const bowler = participantAccumulator(participants, event.bowlerId, event.bowlerName);
    if (event.bowlingCompetitorId !== null) {
      bowler.competitorIds.add(event.bowlingCompetitorId);

      if (event.bowlingCompetitorName !== null) {
        bowler.competitorNames.set(event.bowlingCompetitorId, event.bowlingCompetitorName);
      }
    }
    bowler.bowling ??= {
      runsConceded: 0,
      legalBallsBowled: 0,
      wicketsTaken: 0,
    };
    bowler.bowling.runsConceded +=
      event.runsOffBat + (event.extraWides ?? 0) + (event.extraNoBalls ?? 0);
    if (event.extraWides === null && event.extraNoBalls === null) {
      bowler.bowling.legalBallsBowled += 1;
    }
    bowler.bowling.wicketsTaken += event.creditedWickets;
    addParticipantEvent(bowler, event);
  }

  const participantStatistics = [...participants.values()]
    .sort((left, right) => compareDatabaseIds(left.participantId, right.participantId))
    .map((participant): ParticipantFixtureStatistic => {
      const competitorIds = [...participant.competitorIds].sort(compareDatabaseIds);
      const competitorId = competitorIds[0] ?? null;
      const competitorName =
        competitorId === null ? null : (participant.competitorNames.get(competitorId) ?? null);

      if (competitorId === null) {
        warnings.push({
          code: 'PARTICIPANT_COMPETITOR_UNKNOWN',
          message: 'The participant could not be associated with a fixture competitor.',
          participantId: participant.participantId,
        });
      }

      return {
        statisticId: statisticId(source.fixtureId, 'participant', participant.participantId),
        fixtureId: source.fixtureId,
        scope: 'participant',
        statisticCode: 'participant_fixture',
        participantId: participant.participantId,
        participantName: participant.participantName,
        competitorId,
        competitorName,
        sourceEventCount: participant.events.length,
        batting: participant.batting
          ? {
              ...participant.batting,
              strikeRate: calculateRate(
                participant.batting.runsScored,
                participant.batting.ballsFaced,
                100,
              ),
            }
          : null,
        bowling: participant.bowling
          ? {
              ...participant.bowling,
              oversBowled: formatOvers(participant.bowling.legalBallsBowled, source.ballsPerOver),
              economyRate: calculateRate(
                participant.bowling.runsConceded,
                participant.bowling.legalBallsBowled,
                source.ballsPerOver,
              ),
            }
          : null,
        ...(includeContributors
          ? {
              contributingEvents: participant.events.map((event) =>
                mapContributingEvent(source.fixtureId, event),
              ),
            }
          : {}),
      };
    });

  statistics.push(...participantStatistics);

  return {
    fixtureId: source.fixtureId,
    status: warnings.length === 0 ? 'complete' : 'partial',
    scope: {
      superOversIncluded: false,
    },
    outcome: mapOutcome(source),
    warnings,
    statistics,
  };
}

