import type {
  ApiErrorDetail,
  SubmissionEvent,
  SubmissionRequest,
  CorrectionRequest,
  SubmissionSourceFile,
} from '@sport-analytics/contracts';
import type { Pool, PoolClient } from 'pg';

import {
  DatabaseAccessError,
  executeQuery,
  getDatabasePool,
  type QueryExecutor,
  withTransaction,
} from '../../database';
import {
  SubmissionConflictError,
  SubmissionForbiddenError,
  SubmissionValidationError,
} from './submission.errors';

interface FixtureSubmissionScope {
  fixtureId: string;
  competitionId: string | null;
}

interface AcceptedSubmission {
  submissionId: string;
  fixtureId: string;
  submitterId: string;
  status: 'accepted';
  receivedAt: string;
