import type {
  ApiErrorDetail,
  CurrentUserProfile,
  Fixture,
  SubmissionEvent,
  SubmissionResponse,
} from '@sport-analytics/contracts';
import { useEffect, useRef, useState } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { ApiResponseError } from '../../api/client';
import { useAuth } from '../auth/AuthProvider';
import { getCurrentUserProfile } from '../auth/current-user-api';
import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import { CorrectionWorkspace } from './CorrectionWorkspace';
import {
  listAllFixtures,
  listScopedFixtures,
  SubmissionInputError,
  submitEvents,
  submitSubmissionFile,
} from './submission-api';

const EMPTY_EVENTS = '[]';

type AccessState =
  | { kind: 'loading' }
  | { kind: 'error'; message: string }
  | {
      kind: 'forbidden';
      role: CurrentUserProfile['role'];
      approvalState: CurrentUserProfile['approvalState'];
    }
  | { kind: 'permitted'; fixtures: Fixture[]; role: 'submitter' | 'admin' };

type ResultState =
  | { kind: 'idle' }
  | { kind: 'submitting' }
  | {
      kind: 'accepted';
      response: SubmissionResponse;
      correctionContext?: {
        events: SubmissionEvent[];
        fixture: Fixture;
      };
    }
  | { kind: 'rejected'; message: string; details: ApiErrorDetail[] }
  | { kind: 'error'; message: string };

function usePageTitle() {
  useEffect(() => {
    document.title = "Submit Events | Stat'sTheGame";
  }, []);
}

function formatFixtureOption(fixture: Fixture): string {
  return `${fixture.startDate} â€” ${fixture.matchType}, ${fixture.season} (fixture ${fixture.fixtureId})`;
}

function formatValidationLocation(detail: ApiErrorDetail, uploadedFile: boolean): string {
  const eventLabel =
    detail.eventIndex === undefined
      ? uploadedFile
        ? 'File'
        : 'Submission'
      : `${uploadedFile ? 'Row' : 'Event'} ${detail.eventIndex + 1}`;

  let field = detail.field;

  if (field && detail.eventIndex !== undefined) {
    field = field.replace(new RegExp(`^events\\.${detail.eventIndex}\\.?`), '');
  }

  return field ? `${eventLabel} â€” ${field}` : eventLabel;
}

function AccessError({ message }: { message: string }) {
  return (
    <div className="state-message state-message--error" role="alert">
      <h2>Submission access could not be checked</h2>
      <p>{message}</p>
    </div>
  );
}

function ForbiddenState({
  role,
  approvalState,
}: {
  role: CurrentUserProfile['role'];
  approvalState: CurrentUserProfile['approvalState'];
}) {
  const detail =
    role === 'viewer' && approvalState === 'pending'
      ? 'Your submitter request is pending approval.'
      : 'Your account does not have the submitter role required to submit event data.';

  return (
    <div className="state-message" role="status">
      <h2>Submitter role required</h2>
      <p>{detail} The backend will continue to protect every submission and competition scope.</p>
      <Link className="button button--secondary" to="/account">
        Return to account
      </Link>
    </div>
  );
}

function ValidationResults({
  message,
  details,
  uploadedFile,
}: {
  message: string;
  details: ApiErrorDetail[];
  uploadedFile: boolean;
}) {
  return (
    <div className="submission-result submission-result--error" role="alert">
      <h2 tabIndex={-1} data-result-heading>
        Submission rejected
      </h2>

      <p>{message}</p>

      {details.length > 0 ? (
        <ol className="validation-results">
          {details.map((detail, index) => (
            <li
              key={`${detail.code}-${detail.eventIndex ?? 'submission'}-${detail.field ?? index}`}
            >
              <strong>{formatValidationLocation(detail, uploadedFile)}</strong>
              <span>{detail.message}</span>
            </li>
          ))}
        </ol>
      ) : null}
    </div>
  );
}

function SubmissionForm({ fixtures, role }: { fixtures: Fixture[]; role: 'submitter' | 'admin' }) {
  const client = useAuthenticatedApiClient();

  const [fixtureId, setFixtureId] = useState(fixtures[0]?.fixtureId ?? '');
  const [eventJson, setEventJson] = useState(EMPTY_EVENTS);
  const [mode, setMode] = useState<'file' | 'json'>('file');
  const [file, setFile] = useState<File | null>(null);
  const [result, setResult] = useState<ResultState>({ kind: 'idle' });

  const resultRegionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (result.kind === 'accepted' || result.kind === 'rejected' || result.kind === 'error') {
      resultRegionRef.current?.querySelector<HTMLElement>('[data-result-heading]')?.focus();
    }
  }, [result]);

  function resetResult() {
    if (result.kind !== 'idle' && result.kind !== 'submitting') {
      setResult({ kind: 'idle' });
    }
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (mode === 'file' && !file) {
      setResult({
        kind: 'rejected',
        message: 'Choose a JSON or CSV file before submitting.',
        details: [],
      });
      return;
    }

    setResult({ kind: 'submitting' });

    try {
      if (mode === 'file' && file) {
        const response = await submitSubmissionFile(client, file);

        setResult({
          kind: 'accepted',
          response,
        });
      } else {
        const accepted = await submitEvents(client, fixtureId, eventJson);

        const fixture = fixtures.find(
          (candidate) => candidate.fixtureId === accepted.response.data.fixtureId,
        );

        if (!fixture) {
          throw new SubmissionInputError('Select an available fixture before submitting.');
        }

        setResult({
          kind: 'accepted',
          response: accepted.response,
          correctionContext: {
            events: accepted.events,
            fixture,
          },
        });
      }
    } catch (error) {
      if (error instanceof SubmissionInputError) {
        setResult({
          kind: 'rejected',
          message: error.message,
          details: [],
        });
      } else if (error instanceof ApiResponseError && error.details) {
        setResult({
          kind: 'rejected',
          message: error.message,
          details: error.details,
        });
      } else if (error instanceof ApiResponseError && error.status === 403) {
        setResult({
          kind: 'error',
          message:
            'The backend did not permit this submission. Your approval or fixture scope may have changed.',
        });
      } else {
        setResult({
          kind: 'error',
          message:
            error instanceof ApiResponseError
              ? error.message
              : 'The submission could not be completed. Please try again.',
        });
      }
    }
  }

  if (fixtures.length === 0) {
    return (
      <div className="state-message" role="status">
        <h2>No in-scope fixtures</h2>
        <p>
          Your account has submission access, but it currently has no available fixtures in its
          scope.
        </p>
      </div>
    );
  }

  const resultDescriptionId =
    result.kind === 'rejected' ? 'submission-validation-results' : undefined;

  const competitions = [...new Set(fixtures.map((fixture) => fixture.competitionName))];

  return (
    <>
      <form className="submission-form" onSubmit={handleSubmit}>
        <fieldset className="submission-mode" disabled={result.kind === 'submitting'}>
          <legend>Choose how to submit</legend>

          <p className="field-help">
            Upload is the normal submitter workflow. The technical JSON editor remains available for
            advanced use.
          </p>

          <label>
            <input
              type="radio"
              name="submission-mode"
              value="file"
              checked={mode === 'file'}
              onChange={() => {
                setMode('file');
                resetResult();
              }}
            />
            Upload a JSON or CSV file
          </label>

          <label>
            <input
              type="radio"
              name="submission-mode"
              value="json"
              checked={mode === 'json'}
              onChange={() => {
                setMode('json');
                resetResult();
              }}
            />
            Paste technical JSON
          </label>
        </fieldset>

        <section className="submission-scope" aria-labelledby="submission-scope-title">
          <h2 id="submission-scope-title">
            {role === 'admin' ? 'Administrator submission access' : 'Your authorised competitions'}
          </h2>
          {role === 'admin' ? (
            <p>
              You may submit event data for any competition. The backend confirms your administrator
              role when it receives your submission.
            </p>
          ) : (
            <p>
              {competitions.join(', ')}. The backend checks this scope again when it receives your
              submission.
            </p>
          )}
        </section>

        {mode === 'file' ? (
          <div className="submission-field">
            <label htmlFor="submission-file">Event data file</label>

            <p id="submission-file-help" className="field-help">
              Choose one <code>.json</code> or <code>.csv</code> file up to 1 MB. CSV must use the
              documented header order.{' '}
              <a href="/submission-template.json" download>
                Download a JSON template
              </a>{' '}
              or{' '}
              <a href="/submission-template.csv" download>
                CSV template
              </a>
              .
            </p>

            <input
              id="submission-file"
              type="file"
              accept=".json,application/json,.csv,text/csv"
              onChange={(event) => {
                setFile(event.target.files?.[0] ?? null);
                resetResult();
              }}
              aria-describedby={
                ['submission-file-help', resultDescriptionId].filter(Boolean).join(' ') || undefined
              }
              aria-invalid={result.kind === 'rejected'}
              disabled={result.kind === 'submitting'}
            />

            {file ? (
              <p className="field-help">
                Selected: {file.name} ({Math.ceil(file.size / 1024)} KB)
              </p>
            ) : null}
          </div>
        ) : (
          <>
            <div className="submission-field">
              <label htmlFor="submission-fixture">Fixture</label>

              <select
                id="submission-fixture"
                value={fixtureId}
                onChange={(event) => {
                  setFixtureId(event.target.value);
                  resetResult();
                }}
                disabled={result.kind === 'submitting'}
              >
                {fixtures.map((fixture) => (
                  <option key={fixture.fixtureId} value={fixture.fixtureId}>
                    {formatFixtureOption(fixture)}
                  </option>
                ))}
              </select>

              <p className="field-help">
                {role === 'admin'
                  ? 'Eligible fixtures from every competition appear for administrators.'
                  : 'Only fixtures in your server-returned competition scope appear.'}
              </p>
            </div>

            <div className="submission-field">
              <label htmlFor="submission-events">Delivery events JSON</label>

              <p id="submission-events-help" className="field-help">
                Paste the <code>events</code> array for Basic schema 1.0. Fixture and schema version
                are added automatically. Final statistic totals are derived by the platform and are
                not accepted here.
              </p>

              <textarea
                id="submission-events"
                value={eventJson}
                onChange={(event) => {
                  setEventJson(event.target.value);
                  resetResult();
                }}
                aria-describedby={
                  ['submission-events-help', resultDescriptionId].filter(Boolean).join(' ') ||
                  undefined
                }
                aria-invalid={result.kind === 'rejected'}
                disabled={result.kind === 'submitting'}
                spellCheck={false}
                rows={18}
              />
            </div>
          </>
        )}

        <button
          className="button button--primary"
          type="submit"
          disabled={result.kind === 'submitting'}
        >
          {result.kind === 'submitting'
            ? 'Submittingâ€¦'
            : mode === 'file'
              ? 'Upload and submit file'
              : 'Submit events'}
        </button>

        {result.kind === 'submitting' ? (
          <p className="submission-progress" role="status">
            Validating and storing the submissionâ€¦
          </p>
        ) : null}

        <div id={resultDescriptionId} ref={resultRegionRef}>
          {result.kind === 'accepted' ? (
            <div className="submission-result submission-result--success" role="status">
              <h2 tabIndex={-1} data-result-heading>
                Submission accepted
              </h2>

              <p>
                The backend accepted and stored {result.response.data.eventCount}{' '}
                {result.response.data.eventCount === 1 ? 'event' : 'events'}.
              </p>

              <dl className="submission-reference">
                <div>
                  <dt>Submission reference</dt>
                  <dd>{result.response.data.submissionId}</dd>
                </div>

                <div>
                  <dt>Fixture</dt>
                  <dd>{result.response.data.fixtureId}</dd>
                </div>

                <div>
                  <dt>Received</dt>
                  <dd>{new Date(result.response.data.receivedAt).toLocaleString()}</dd>
                </div>
              </dl>
            </div>
          ) : result.kind === 'rejected' ? (
            <ValidationResults
              message={result.message}
              details={result.details}
              uploadedFile={mode === 'file'}
            />
          ) : result.kind === 'error' ? (
            <div className="submission-result submission-result--error" role="alert">
              <h2 tabIndex={-1} data-result-heading>
                Submission failed
              </h2>
              <p>{result.message}</p>
            </div>
          ) : null}
        </div>
      </form>

      {result.kind === 'accepted' && result.correctionContext ? (
        <CorrectionWorkspace
          fixture={result.correctionContext.fixture}
          initialEvents={result.correctionContext.events}
          key={result.response.data.submissionId}
        />
      ) : null}
    </>
  );
}

export function SubmissionPage() {
  const { isAuthenticated, isLoading } = useAuth();
  const client = useAuthenticatedApiClient();

  const [accessState, setAccessState] = useState<AccessState>({
    kind: 'loading',
  });

  usePageTitle();

  useEffect(() => {
    if (isLoading || !isAuthenticated) {
      return;
    }

    const controller = new AbortController();

    setAccessState({ kind: 'loading' });

    void getCurrentUserProfile(client, controller.signal)
      .then(async (profile) => {
        if (profile.role !== 'submitter' && profile.role !== 'admin') {
          setAccessState({
            kind: 'forbidden',
            role: profile.role,
            approvalState: profile.approvalState,
          });
          return;
        }

        const fixtures =
          profile.role === 'admin'
            ? await listAllFixtures(controller.signal)
            : await listScopedFixtures(profile.competitionIds, controller.signal);

        setAccessState({
          kind: 'permitted',
          fixtures,
          role: profile.role,
        });
      })
      .catch((error: unknown) => {
        if (controller.signal.aborted) {
          return;
        }

        setAccessState({
          kind: 'error',
          message:
            error instanceof ApiResponseError && error.kind === 'unauthenticated'
              ? 'Your session is no longer valid. Sign in again to continue.'
              : 'Your application role and fixture scope could not be loaded. Please try again.',
        });
      });

    return () => controller.abort();
  }, [client, isAuthenticated, isLoading]);

  if (!isLoading && !isAuthenticated) {
    return <Navigate to="/sign-in" replace />;
  }

  return (
    <section className="submission-page content-boundary" aria-labelledby="submission-page-title">
      <header className="page-heading submission-page__heading">
        <p className="eyebrow">Submitter workspace</p>
        <h1 id="submission-page-title">Submit Delivery Events</h1>
        <p>
          Select an authorised fixture and send ordered delivery events for backend validation and
          storage.
        </p>
      </header>

      {isLoading || accessState.kind === 'loading' ? (
        <div className="state-message" role="status">
          <h2>Checking submission access</h2>
          <p>Loading your persisted role and competition scopeâ€¦</p>
        </div>
      ) : accessState.kind === 'error' ? (
        <AccessError message={accessState.message} />
      ) : accessState.kind === 'forbidden' ? (
        <ForbiddenState role={accessState.role} approvalState={accessState.approvalState} />
      ) : (
        <SubmissionForm fixtures={accessState.fixtures} role={accessState.role} />
      )}
    </section>
  );
}
import type {
  ApiErrorDetail,
  Fixture,
  Participant,
  SubmissionEvent,
} from '@sport-analytics/contracts';
import { useCallback, useEffect, useId, useRef, useState } from 'react';
import { ApiResponseError } from '../../api/client';
import { TextField } from '../../components/TextField';
import { publicReadApi } from '../../api/public-read';
import { usePublicData } from '../browse/usePublicData';
import { FixtureStatisticsOverview } from '../statistics/StatisticsPages';
import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import { correctEvent } from './correction-api';

type CorrectionResult =
  | { kind: 'idle' }
  | { kind: 'submitting' }
  | { kind: 'accepted'; revision: number }
  | { kind: 'rejected'; message: string }
  | { kind: 'error'; message: string }
  | { kind: 'denied' };

type FieldErrors = Record<string, string>;

function eventLabel(event: SubmissionEvent): string {
  return `Delivery ${event.sequenceNumber} - ball ${event.ballNumber}`;
}

function fieldKey(detail: ApiErrorDetail): string {
  const field = detail.field?.replace(/^event\./, '') ?? 'eventId';

  if (field === 'runs.total') {
    return 'runs.offBat';
  }

  if (field === 'runs.extras' || field.startsWith('extras.')) {
    return field === 'runs.extras' ? 'extras' : field;
  }

  if (field.startsWith('wickets')) {
    return 'wickets';
  }

  return field;
}

function detailsToFieldErrors(details: ApiErrorDetail[]): FieldErrors {
  return details.reduce<FieldErrors>((errors, detail) => {
    const key = fieldKey(detail);
    errors[key] = errors[key] ? `${errors[key]} ${detail.message}` : detail.message;
    return errors;
  }, {});
}

function participantName(participants: Participant[], participantId: string): string {
  return (
    participants.find((participant) => participant.participantId === participantId)?.displayName ??
    'Participant unavailable'
  );
}

interface ParticipantSelectProps {
  disabled: boolean;
  error?: string;
  id: string;
  label: string;
  onChange: (participantId: string) => void;
  participants: Participant[];
  value: string;
}

function ParticipantSelect({
  disabled,
  error,
  id,
  label,
  onChange,
  participants,
  value,
}: ParticipantSelectProps) {
  const errorId = error ? `${id}-error` : undefined;

  return (
    <div className="ui-field">
      <label htmlFor={id}>{label}</label>
      <select
        aria-describedby={errorId}
        aria-invalid={error ? true : undefined}
        className="ui-field__input"
        disabled={disabled}
        id={id}
        onChange={(changeEvent) => onChange(changeEvent.target.value)}
        value={value}
      >
        {!participants.some((participant) => participant.participantId === value) ? (
          <option value={value}>{participantName(participants, value)}</option>
        ) : null}
        {participants.map((participant) => (
          <option key={participant.participantId} value={participant.participantId}>
            {participant.displayName}
          </option>
        ))}
      </select>
      {error ? (
        <p className="ui-field__error" id={errorId}>
          {error}
        </p>
      ) : null}
    </div>
  );
}

function numberValue(value: string): number {
  return Number.parseInt(value, 10) || 0;
}

function extraTotal(event: SubmissionEvent): number {
  return Object.values(event.extras).reduce<number>((total, value) => total + (value ?? 0), 0);
}

interface CorrectionFormProps {
  event: SubmissionEvent;
  fieldErrors: FieldErrors;
  fixture: Fixture;
  onChange: (event: SubmissionEvent) => void;
  onSubmit: (event: React.FormEvent<HTMLFormElement>, wicketsJson: string) => void;
  participants: Participant[];
  result: CorrectionResult;
}

function CorrectionForm({
  event,
  fieldErrors,
  fixture,
  onChange,
  onSubmit,
  participants,
  result,
}: CorrectionFormProps) {
  const disabled = result.kind === 'submitting';
  const [wicketsJson, setWicketsJson] = useState(() => JSON.stringify(event.wickets, null, 2));
  const extras = extraTotal(event);

  useEffect(() => {
    setWicketsJson(JSON.stringify(event.wickets, null, 2));
  }, [event.eventId, event.wickets]);

  function update<Key extends keyof SubmissionEvent>(key: Key, value: SubmissionEvent[Key]) {
    onChange({ ...event, [key]: value });
  }

  function updateExtra(key: keyof SubmissionEvent['extras'], value: number) {
    onChange({
      ...event,
      runs: { ...event.runs, extras: extras - (event.extras[key] ?? 0) + value },
      extras: { ...event.extras, [key]: value },
    });
  }

  const totalRuns = event.runs.offBat + extras;

  return (
    <form
      className="correction-form"
      onSubmit={(submitEvent) => onSubmit(submitEvent, wicketsJson)}
    >
      <header className="correction-form__heading">
        <div>
          <p className="eyebrow">Current accepted event</p>
          <h3>{eventLabel(event)}</h3>
        </div>
        <p>{fixture.competitors.map((team) => team.name).join(' vs ')}</p>
      </header>

      <dl className="correction-event-reference">
        <div>
          <dt>Event reference</dt>
          <dd
            aria-describedby={fieldErrors.eventId ? 'correction-event-reference-error' : undefined}
          >
            {event.eventId}
          </dd>
          {fieldErrors.eventId ? (
            <dd className="ui-field__error" id="correction-event-reference-error">
              {fieldErrors.eventId}
            </dd>
          ) : null}
        </div>
        <div>
          <dt>Occurrence order</dt>
          <dd>{event.sequenceNumber} (kept by the backend)</dd>
        </div>
      </dl>

      <fieldset className="correction-fieldset">
        <legend>Delivery position</legend>
        <div className="correction-form__grid">
          <TextField
            disabled={disabled}
            error={fieldErrors.inningsId ?? ''}
            id="correction-innings"
            label="Innings reference"
            onChange={(changeEvent) => update('inningsId', changeEvent.target.value)}
            required
            value={event.inningsId}
          />
          <TextField
            disabled={disabled}
            error={fieldErrors.overNumber ?? ''}
            id="correction-over"
            label="Over number"
            min={0}
            onChange={(changeEvent) => update('overNumber', numberValue(changeEvent.target.value))}
            required
            type="number"
            value={event.overNumber}
          />
          <TextField
            disabled={disabled}
            error={fieldErrors.positionInOver ?? ''}
            id="correction-position"
            label="Delivery position in over"
            min={0}
            onChange={(changeEvent) =>
              update('positionInOver', numberValue(changeEvent.target.value))
            }
            required
            type="number"
            value={event.positionInOver}
          />
          <TextField
            disabled={disabled}
            error={fieldErrors.ballNumber ?? ''}
            helpText="Use the printed cricket form, for example 5.1."
            id="correction-ball-number"
            label="Printed ball number"
            onChange={(changeEvent) => update('ballNumber', changeEvent.target.value)}
            required
            value={event.ballNumber}
          />
        </div>
      </fieldset>

      <fieldset className="correction-fieldset">
        <legend>Players</legend>
        <div className="correction-form__grid">
          <ParticipantSelect
            disabled={disabled}
            error={fieldErrors.strikerId ?? ''}
            id="correction-striker"
            label="Striker"
            onChange={(participantId) => update('strikerId', participantId)}
            participants={participants}
            value={event.strikerId}
          />
          <ParticipantSelect
            disabled={disabled}
            error={fieldErrors.nonStrikerId ?? ''}
            id="correction-non-striker"
            label="Non-striker"
            onChange={(participantId) => update('nonStrikerId', participantId)}
            participants={participants}
            value={event.nonStrikerId}
          />
          <ParticipantSelect
            disabled={disabled}
            error={fieldErrors.bowlerId ?? ''}
            id="correction-bowler"
            label="Bowler"
            onChange={(participantId) => update('bowlerId', participantId)}
            participants={participants}
            value={event.bowlerId}
          />
        </div>
      </fieldset>

      <fieldset className="correction-fieldset">
        <legend>Runs and extras</legend>
        <div className="correction-form__grid">
          <TextField
            disabled={disabled}
            error={fieldErrors['runs.offBat'] ?? ''}
            id="correction-off-bat"
            label="Runs off the bat"
            min={0}
            onChange={(changeEvent) =>
              update('runs', {
                ...event.runs,
                offBat: numberValue(changeEvent.target.value),
                extras,
                total: numberValue(changeEvent.target.value) + extras,
              })
            }
            required
            type="number"
            value={event.runs.offBat}
          />
          {(
            [
              ['wides', 'Wides'],
              ['noBalls', 'No-balls'],
              ['byes', 'Byes'],
              ['legByes', 'Leg-byes'],
              ['penalty', 'Penalty extras'],
            ] as const
          ).map(([key, label]) => (
            <TextField
              disabled={disabled}
              error={fieldErrors[`extras.${key}`] ?? fieldErrors.extras ?? ''}
              id={`correction-${key}`}
              key={key}
              label={label}
              min={0}
              onChange={(changeEvent) => updateExtra(key, numberValue(changeEvent.target.value))}
              required
              type="number"
              value={event.extras[key] ?? 0}
            />
          ))}
        </div>
        <dl className="correction-derived-values" aria-label="Read-only derived event values">
          <div>
            <dt>Delivery extras</dt>
            <dd>{extras}</dd>
          </div>
          <div>
            <dt>Delivery total</dt>
            <dd>{totalRuns}</dd>
          </div>
        </dl>
        <p className="field-help">
          These delivery values are calculated from the editable run fields. Published match and
          player statistics remain read-only and are recalculated by the backend.
        </p>
        <label className="correction-checkbox" htmlFor="correction-non-boundary">
          <input
            checked={event.runs.nonBoundary}
            disabled={disabled}
            id="correction-non-boundary"
            onChange={(changeEvent) =>
              update('runs', { ...event.runs, nonBoundary: changeEvent.target.checked })
            }
            type="checkbox"
          />
          Mark runs off the bat as non-boundary runs
        </label>
      </fieldset>

      <div className="submission-field correction-wickets-field">
        <label htmlFor="correction-wickets">Wickets on this delivery</label>
        <p className="field-help" id="correction-wickets-help">
          Edit the prefilled Basic schema wicket array. Use an empty array when no wicket fell.
        </p>
        <textarea
          aria-describedby={[
            'correction-wickets-help',
            fieldErrors.wickets ? 'correction-wickets-error' : null,
          ]
            .filter(Boolean)
            .join(' ')}
          aria-invalid={fieldErrors.wickets ? true : undefined}
          disabled={disabled}
          id="correction-wickets"
          onChange={(changeEvent) => setWicketsJson(changeEvent.target.value)}
          rows={8}
          spellCheck={false}
          value={wicketsJson}
        />
        {fieldErrors.wickets ? (
          <p className="ui-field__error" id="correction-wickets-error">
            {fieldErrors.wickets}
          </p>
        ) : null}
      </div>

      <button className="button button--primary" disabled={disabled} type="submit">
        {disabled ? 'Saving correction...' : 'Save correction'}
      </button>
    </form>
  );
}

export function CorrectionWorkspace({
  fixture,
  initialEvents,
}: {
  fixture: Fixture;
  initialEvents: SubmissionEvent[];
}) {
  const client = useAuthenticatedApiClient();
  const headingId = useId();
  const resultRegionRef = useRef<HTMLDivElement>(null);
  const [events, setEvents] = useState(initialEvents);
  const [selectedEventId, setSelectedEventId] = useState(initialEvents[0]?.eventId ?? '');
  const [draft, setDraft] = useState(initialEvents[0]);
  const [result, setResult] = useState<CorrectionResult>({ kind: 'idle' });
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [statisticsRefresh, setStatisticsRefresh] = useState(0);
  const loadParticipants = useCallback(
    (signal: AbortSignal) =>
      publicReadApi.listParticipants(
        `?fixtureId=${encodeURIComponent(fixture.fixtureId)}&limit=100`,
        signal,
      ),
    [fixture.fixtureId],
  );
  const participantsState = usePublicData(loadParticipants, fixture.fixtureId);

  useEffect(() => {
    if (
      result.kind === 'accepted' ||
      result.kind === 'rejected' ||
      result.kind === 'error' ||
      result.kind === 'denied'
    ) {
      resultRegionRef.current
        ?.querySelector<HTMLElement>('[data-correction-result-heading]')
        ?.focus();
    }
  }, [result]);

  function chooseEvent(eventId: string) {
    const selected = events.find((event) => event.eventId === eventId);
    setSelectedEventId(eventId);
    setDraft(selected);
    setResult({ kind: 'idle' });
    setFieldErrors({});
  }

  async function handleCorrection(
    submitEvent: React.FormEvent<HTMLFormElement>,
    wicketsJson: string,
  ) {
    submitEvent.preventDefault();
    if (!draft) {
      return;
    }

    let wickets: SubmissionEvent['wickets'];
    try {
      const parsed = JSON.parse(wicketsJson) as unknown;
      if (!Array.isArray(parsed)) {
        throw new Error();
      }
      wickets = parsed as SubmissionEvent['wickets'];
    } catch {
      setFieldErrors({ wickets: 'Enter a valid JSON array of wickets.' });
      setResult({ kind: 'rejected', message: 'The correction contains invalid wicket data.' });
      return;
    }

    const correctedDraft = {
      ...draft,
      runs: {
        ...draft.runs,
        extras: extraTotal(draft),
        total: draft.runs.offBat + extraTotal(draft),
      },
      wickets,
    };
    setResult({ kind: 'submitting' });
    setFieldErrors({});

    try {
      const response = await correctEvent(client, fixture.fixtureId, correctedDraft);
      setEvents((currentEvents) =>
        currentEvents.map((event) =>
          event.eventId === correctedDraft.eventId ? correctedDraft : event,
        ),
      );
      setDraft(correctedDraft);
      setResult({ kind: 'accepted', revision: response.data.revision });
      setStatisticsRefresh((value) => value + 1);
    } catch (error) {
      if (error instanceof ApiResponseError && (error.status === 401 || error.status === 403)) {
        setResult({ kind: 'denied' });
      } else if (error instanceof ApiResponseError && error.status === 409) {
        setFieldErrors({
          eventId: error.message,
          inningsId: error.message,
          overNumber: error.message,
          positionInOver: error.message,
        });
        setResult({
          kind: 'rejected',
          message:
            'This event changed or its delivery position now conflicts with another accepted event. Review the highlighted event position before trying again.',
        });
      } else if (error instanceof ApiResponseError && error.details) {
        setFieldErrors(detailsToFieldErrors(error.details));
        setResult({ kind: 'rejected', message: error.message });
      } else {
        setResult({
          kind: 'error',
          message:
            error instanceof Error
              ? error.message
              : 'The correction could not be saved. The current event remains unchanged.',
        });
      }
    }
  }

  return (
    <section aria-labelledby={headingId} className="correction-workspace">
      <div className="statistics-section-heading">
        <div>
          <p className="eyebrow">Accepted submission</p>
          <h2 id={headingId}>Correct an accepted event</h2>
        </div>
        <p>{events.length} available</p>
      </div>
      <p className="correction-workspace__intro">
        Choose an event from this accepted submission. The form keeps the event identity and
        occurrence order while the backend validates and stores an immutable correction.
      </p>

      {result.kind === 'denied' ? (
        <div className="state-message state-message--error" ref={resultRegionRef} role="alert">
          <h3 data-correction-result-heading tabIndex={-1}>
            Correction access denied
          </h3>
          <p>
            Your session, submitter role, or competition scope no longer permits this correction.
            The accepted event was not changed.
          </p>
        </div>
      ) : participantsState.status === 'loading' ? (
        <div className="state-message" role="status">
          <h3>Loading correction labels</h3>
          <p>Loading the participating player names for this match...</p>
        </div>
      ) : participantsState.status === 'error' ? (
        <div className="state-message state-message--error" role="alert">
          <h3>Correction form could not be loaded</h3>
          <p>Player labels are unavailable, so no correction action is offered.</p>
          <button
            className="button button--secondary"
            onClick={participantsState.reload}
            type="button"
          >
            Try again
          </button>
        </div>
      ) : (
        <>
          {events.length > 1 ? (
            <div className="submission-field correction-event-picker">
              <label htmlFor="correction-event">Accepted event</label>
              <select
                disabled={result.kind === 'submitting'}
                id="correction-event"
                onChange={(changeEvent) => chooseEvent(changeEvent.target.value)}
                value={selectedEventId}
              >
                {events.map((event) => (
                  <option key={event.eventId} value={event.eventId}>
                    {eventLabel(event)}
                  </option>
                ))}
              </select>
            </div>
          ) : null}

          {draft ? (
            <CorrectionForm
              event={draft}
              fieldErrors={fieldErrors}
              fixture={fixture}
              onChange={(changedEvent) => {
                setDraft(changedEvent);
                if (result.kind !== 'idle' && result.kind !== 'submitting') {
                  setResult({ kind: 'idle' });
                  setFieldErrors({});
                }
              }}
              onSubmit={handleCorrection}
              participants={participantsState.data.data}
              result={result}
            />
          ) : null}

          <div ref={resultRegionRef}>
            {result.kind === 'accepted' ? (
              <div className="submission-result submission-result--success" role="status">
                <h3 data-correction-result-heading tabIndex={-1}>
                  Correction saved
                </h3>
                <p>
                  Revision {result.revision} is now current. The displayed event and match
                  statistics below have been refreshed.
                </p>
              </div>
            ) : result.kind === 'rejected' ? (
              <div className="submission-result submission-result--error" role="alert">
                <h3 data-correction-result-heading tabIndex={-1}>
                  Correction rejected
                </h3>
                <p>{result.message} The accepted event was not changed.</p>
              </div>
            ) : result.kind === 'error' ? (
              <div className="submission-result submission-result--error" role="alert">
                <h3 data-correction-result-heading tabIndex={-1}>
                  Correction failed
                </h3>
                <p>{result.message}</p>
              </div>
            ) : null}
          </div>
        </>
      )}

      <FixtureStatisticsOverview
        fixtureId={fixture.fixtureId}
        key={`${fixture.fixtureId}:${statisticsRefresh}`}
      />
    </section>
  );
}
import {
  DIRECT_SUBMISSION_SCHEMA_VERSION,
  submissionRequestSchema,
  submissionResponseSchema,
  type Fixture,
  type SubmissionEvent,
  type SubmissionResponse,
} from '@sport-analytics/contracts';
import type { AuthenticatedApiClient } from '../../api/client';
import { publicReadApi } from '../../api/public-read';

class SubmissionInterfaceContractError extends Error {
  constructor() {
    super('The API returned an unexpected response. Please try again.');
    this.name = 'SubmissionInterfaceContractError';
  }
}

export class SubmissionInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubmissionInputError';
  }
}

async function listCompetitionFixtures(
  competitionId: string,
  signal?: AbortSignal,
): Promise<Fixture[]> {
  const fixtures: Fixture[] = [];
  let cursor: string | null = null;

  do {
    const parameters = new URLSearchParams({ competitionId, limit: '100' });
    if (cursor) {
      parameters.set('cursor', cursor);
    }

    const response = await publicReadApi.listFixtures(`?${parameters.toString()}`, signal);
    fixtures.push(...response.data);
    cursor = response.pagination.nextCursor;
  } while (cursor);

  return fixtures;
}

export async function listAllFixtures(signal?: AbortSignal): Promise<Fixture[]> {
  const fixtures: Fixture[] = [];
  let cursor: string | null = null;

  do {
    const parameters = new URLSearchParams({ limit: '100' });
    if (cursor) {
      parameters.set('cursor', cursor);
    }

    const response = await publicReadApi.listFixtures(`?${parameters.toString()}`, signal);
    fixtures.push(...response.data);
    cursor = response.pagination.nextCursor;
  } while (cursor);

  return fixtures
    .filter((fixture) => fixture.competitionId !== null)
    .sort(
      (left, right) =>
        left.startDate.localeCompare(right.startDate) ||
        left.fixtureId.localeCompare(right.fixtureId),
    );
}

export async function listScopedFixtures(
  competitionIds: string[],
  signal?: AbortSignal,
): Promise<Fixture[]> {
  const fixtureGroups = await Promise.all(
    competitionIds.map((competitionId) => listCompetitionFixtures(competitionId, signal)),
  );
  const fixturesById = new Map<string, Fixture>();

  for (const fixture of fixtureGroups.flat()) {
    if (fixture.competitionId && competitionIds.includes(fixture.competitionId)) {
      fixturesById.set(fixture.fixtureId, fixture);
    }
  }

  return [...fixturesById.values()].sort(
    (left, right) =>
      left.startDate.localeCompare(right.startDate) ||
      left.fixtureId.localeCompare(right.fixtureId),
  );
}

export async function submitEvents(
  client: AuthenticatedApiClient,
  fixtureId: string,
  eventJson: string,
): Promise<{ response: SubmissionResponse; events: SubmissionEvent[] }> {
  let events: unknown;

  try {
    events = JSON.parse(eventJson) as unknown;
  } catch {
    throw new SubmissionInputError('Enter valid JSON before submitting.');
  }

  if (!Array.isArray(events)) {
    throw new SubmissionInputError('The event JSON must be an array of delivery events.');
  }

  const payload = {
    fixtureId,
    schemaVersion: DIRECT_SUBMISSION_SCHEMA_VERSION,
    events: events as SubmissionEvent[],
  };
  const response = await client.request<unknown>('/submissions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const parsed = submissionResponseSchema.safeParse(response);
  const acceptedPayload = submissionRequestSchema.safeParse(payload);

  if (!parsed.success || !acceptedPayload.success) {
    throw new SubmissionInterfaceContractError();
  }

  return { response: parsed.data, events: acceptedPayload.data.events };
}

export async function submitSubmissionFile(
  client: AuthenticatedApiClient,
  file: File,
): Promise<SubmissionResponse> {
  const formData = new FormData();
  formData.append('file', file);

  const response = await client.request<unknown>('/submissions/uploads', {
    method: 'POST',
    body: formData,
  });
  const parsed = submissionResponseSchema.safeParse(response);

  if (!parsed.success) {
    throw new SubmissionInterfaceContractError();
  }

  return parsed.data;
}
import {
  correctionResponseSchema,
  DIRECT_SUBMISSION_SCHEMA_VERSION,
  type CorrectionResponse,
  type SubmissionEvent,
} from '@sport-analytics/contracts';
import type { AuthenticatedApiClient } from '../../api/client';

class CorrectionInterfaceContractError extends Error {
  constructor() {
    super('The API returned an unexpected correction response. Please try again.');
    this.name = 'CorrectionInterfaceContractError';
  }
}

export async function correctEvent(
  client: AuthenticatedApiClient,
  fixtureId: string,
  event: SubmissionEvent,
): Promise<CorrectionResponse> {
  const { eventId, sequenceNumber: _sequenceNumber, ...correctedEvent } = event;
  void _sequenceNumber;

  const response = await client.request<unknown>(
    `/submissions/events/${encodeURIComponent(eventId)}`,
    {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        fixtureId,
        schemaVersion: DIRECT_SUBMISSION_SCHEMA_VERSION,
        event: correctedEvent,
      }),
    },
  );
  const parsed = correctionResponseSchema.safeParse(response);

  if (!parsed.success) {
    throw new CorrectionInterfaceContractError();
  }

  return parsed.data;
}

