      return queryAcceptedFixtureEvents(database(), options);
    },

    async findAcceptedFixtureEvent(fixtureId, eventId) {
      const page = await queryAcceptedFixtureEvents(database(), {
        fixtureId,
        eventId,
        limit: 1,
      });

      return page.records[0] ?? null;
    },
  };
}
