-- Up Migration

-- Durable staging and resume metadata for the batch-ingestion design in
-- docs/architecture/batch-ingestion-pipeline.md. Processing, review and object
-- storage remain separate follow-on work.
--
-- Refs #276

CREATE TYPE batch_state AS ENUM (
    'received',
    'stored',
    'validating',
    'rejected',
    'awaiting_review',
    'publishing',
    'published',
    'partially_published',
    'failed',
    'superseded'
);

CREATE TYPE batch_item_state AS ENUM (
    'pending',
    'accepted',
    'rejected',
    'published',
    'duplicate_skipped'
);

CREATE TYPE batch_checkpoint_phase AS ENUM ('validating', 'publishing');

CREATE TABLE batch (
    batch_id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    submitter_id      bigint NOT NULL REFERENCES app_user (app_user_id) ON DELETE RESTRICT,
    competition_id    bigint NOT NULL REFERENCES competition (competition_id) ON DELETE RESTRICT,
    idempotency_key   text NOT NULL,
    source_checksum   char(64),
    source_uri        text,
    source_size_bytes bigint,
    state             batch_state NOT NULL DEFAULT 'received',
    item_count        integer NOT NULL DEFAULT 0,
    superseded_by     bigint REFERENCES batch (batch_id) ON DELETE RESTRICT,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT batch_submitter_idempotency_key UNIQUE (submitter_id, idempotency_key),
    CONSTRAINT batch_idempotency_key_ck CHECK (length(btrim(idempotency_key)) > 0),
    CONSTRAINT batch_source_provenance_ck CHECK (
        (
            source_checksum IS NULL
            AND source_uri IS NULL
            AND source_size_bytes IS NULL
        )
        OR
        (
            source_checksum IS NOT NULL
            AND source_uri IS NOT NULL
            AND source_size_bytes IS NOT NULL
            AND source_checksum ~ '^[0-9A-Fa-f]{64}$'
            AND length(btrim(source_uri)) > 0
            AND source_size_bytes > 0
        )
    ),
    CONSTRAINT batch_item_count_ck CHECK (item_count >= 0),
    CONSTRAINT batch_superseded_by_ck CHECK (
        superseded_by IS NULL OR superseded_by <> batch_id
    )
);

COMMENT ON TABLE batch IS
    'One durable batch-ingestion payload and its lifecycle, source identity and submitter provenance.';

COMMENT ON COLUMN batch.idempotency_key IS
    'Submitter-provided key, unique within one submitter account.';

COMMENT ON COLUMN batch.source_checksum IS
    'SHA-256 checksum of the original object bytes; null while the batch is only received.';

COMMENT ON COLUMN batch.source_uri IS
    'Private object-storage key or URI; never a submitter-facing public URL.';

CREATE FUNCTION set_batch_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER batch_set_updated_at
    BEFORE UPDATE ON batch
    FOR EACH ROW
    EXECUTE FUNCTION set_batch_updated_at();

CREATE FUNCTION prevent_batch_provenance_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'Batch and batch-item provenance records cannot be deleted.'
        USING ERRCODE = '23514';
END;
$$;

CREATE TRIGGER batch_prevent_delete
    BEFORE DELETE ON batch
    FOR EACH ROW
    EXECUTE FUNCTION prevent_batch_provenance_delete();

CREATE TABLE batch_item (
    batch_item_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch_id           bigint NOT NULL REFERENCES batch (batch_id) ON DELETE RESTRICT,
    ordinal            integer NOT NULL,
    innings_id         bigint NOT NULL REFERENCES innings (innings_id) ON DELETE RESTRICT,
    over_number        smallint NOT NULL,
    position_in_over   smallint NOT NULL,
    payload            jsonb NOT NULL,
    state              batch_item_state NOT NULL DEFAULT 'pending',
    rejection_code     text,
    rejection_detail   jsonb,
    published_event_id bigint REFERENCES delivery (delivery_id) ON DELETE RESTRICT,

    CONSTRAINT batch_item_batch_ordinal_key UNIQUE (batch_id, ordinal),
    CONSTRAINT batch_item_batch_natural_key UNIQUE (
        batch_id,
        innings_id,
        over_number,
        position_in_over
    ),
    CONSTRAINT batch_item_ordinal_ck CHECK (ordinal >= 0),
    CONSTRAINT batch_item_over_number_ck CHECK (over_number >= 0),
    CONSTRAINT batch_item_position_in_over_ck CHECK (position_in_over >= 0),
    CONSTRAINT batch_item_published_event_ck CHECK (
        state <> 'published' OR published_event_id IS NOT NULL
    )
);

COMMENT ON TABLE batch_item IS
    'One expanded payload event, ordered by its zero-based payload ordinal and retained before publication.';

COMMENT ON COLUMN batch_item.position_in_over IS
    'The delivery natural-key position. Printed ballNumber remains payload display data and is not an identity column.';

COMMENT ON COLUMN batch_item.published_event_id IS
    'Delivery revision created when this staged item is published.';

CREATE TRIGGER batch_item_prevent_delete
    BEFORE DELETE ON batch_item
    FOR EACH ROW
    EXECUTE FUNCTION prevent_batch_provenance_delete();

CREATE TABLE batch_checkpoint (
    batch_id          bigint PRIMARY KEY REFERENCES batch (batch_id) ON DELETE RESTRICT,
    phase             batch_checkpoint_phase NOT NULL,
    last_ordinal      integer NOT NULL,
    lease_owner       text,
    lease_expires_at  timestamptz,
    attempt_count     integer NOT NULL DEFAULT 0,

    CONSTRAINT batch_checkpoint_last_ordinal_ck CHECK (last_ordinal >= 0),
    CONSTRAINT batch_checkpoint_lease_ck CHECK (
        (lease_owner IS NULL) = (lease_expires_at IS NULL)
        AND (lease_owner IS NULL OR length(btrim(lease_owner)) > 0)
    ),
    CONSTRAINT batch_checkpoint_attempt_count_ck CHECK (attempt_count >= 0)
);

COMMENT ON TABLE batch_checkpoint IS
    'The single durable resume point for a batch phase; chunk work and this row must be written in one transaction.';

COMMENT ON COLUMN batch_checkpoint.last_ordinal IS
    'Highest payload ordinal durably completed in the recorded phase.';

-- The existing delivery_natural_key_live partial unique index already enforces
-- one live delivery revision per natural key. It is intentionally left unchanged.

-- Down Migration

DROP TABLE IF EXISTS batch_checkpoint;

DROP TRIGGER IF EXISTS batch_item_prevent_delete ON batch_item;
DROP TABLE IF EXISTS batch_item;

DROP TRIGGER IF EXISTS batch_prevent_delete ON batch;
DROP FUNCTION IF EXISTS prevent_batch_provenance_delete();
DROP TRIGGER IF EXISTS batch_set_updated_at ON batch;
DROP FUNCTION IF EXISTS set_batch_updated_at();

DROP TABLE IF EXISTS batch;

DROP TYPE IF EXISTS batch_checkpoint_phase;
DROP TYPE IF EXISTS batch_item_state;
DROP TYPE IF EXISTS batch_state;
import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

type BatchState =
  | 'received'
  | 'stored'
  | 'validating'
  | 'rejected'
  | 'awaiting_review'
  | 'publishing'
  | 'published'
  | 'partially_published'
  | 'failed'
  | 'superseded';

type BatchItemState = 'pending' | 'accepted' | 'rejected' | 'published' | 'duplicate_skipped';

type BatchCheckpointPhase = 'validating' | 'publishing';

type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };

interface BatchSource {
  checksum: string;
  uri: string;
  sizeBytes: number;
}

interface BatchRecord {
  batchId: string;
  submitterId: string;
  competitionId: string;
  idempotencyKey: string;
  source: BatchSource | null;
  state: BatchState;
  itemCount: number;
  supersededBy: string | null;
  createdAt: string;
  updatedAt: string;
}

interface CreateBatchInput {
  submitterId: string;
  competitionId: string;
  idempotencyKey: string;
  source?: BatchSource;
  state?: BatchState;
}

interface InsertBatchItemInput {
  ordinal: number;
  inningsId: string;
  overNumber: number;
  positionInOver: number;
  payload: JsonValue;
  state?: BatchItemState;
  rejectionCode?: string | null;
  rejectionDetail?: JsonValue | null;
  publishedEventId?: string | null;
}

interface BatchItemRecord {
  batchItemId: string;
  batchId: string;
  ordinal: number;
  inningsId: string;
  overNumber: number;
  positionInOver: number;
  payload: JsonValue;
  state: BatchItemState;
  rejectionCode: string | null;
  rejectionDetail: JsonValue | null;
  publishedEventId: string | null;
}

interface BatchItemPageOptions {
  afterOrdinal?: number;
  limit: number;
}
interface BatchCheckpointRecord {
  batchId: string;
  phase: BatchCheckpointPhase;
  lastOrdinal: number;
  leaseOwner: string | null;
  leaseExpiresAt: string | null;
  attemptCount: number;
}

interface UpsertBatchCheckpointInput {
  batchId: string;
  phase: BatchCheckpointPhase;
  lastOrdinal: number;
  leaseOwner?: string | null;
  leaseExpiresAt?: string | null;
  attemptCount: number;
}

export interface BatchRepository {
  createBatch(input: CreateBatchInput): Promise<BatchRecord>;
  findBatchById(batchId: string): Promise<BatchRecord | null>;
  findBatchByIdempotencyKey(
    submitterId: string,
    idempotencyKey: string,
  ): Promise<BatchRecord | null>;
  insertBatchItems(batchId: string, items: InsertBatchItemInput[]): Promise<BatchItemRecord[]>;
  listBatchItems(batchId: string, options: BatchItemPageOptions): Promise<BatchItemRecord[]>;
  findCheckpoint(batchId: string): Promise<BatchCheckpointRecord | null>;
  upsertCheckpoint(input: UpsertBatchCheckpointInput): Promise<BatchCheckpointRecord>;
}

interface BatchRow {
  batchId: string;
  submitterId: string;
  competitionId: string;
  idempotencyKey: string;
  sourceChecksum: string | null;
  sourceUri: string | null;
  sourceSizeBytes: string | null;
  state: BatchState;
  itemCount: number;
  supersededBy: string | null;
  createdAt: Date;
  updatedAt: Date;
}

interface BatchCheckpointRow {
  batchId: string;
  phase: BatchCheckpointPhase;
  lastOrdinal: number;
  leaseOwner: string | null;
  leaseExpiresAt: Date | null;
  attemptCount: number;
}

const batchSelection = `
  batch_id::text AS "batchId",
  submitter_id::text AS "submitterId",
  competition_id::text AS "competitionId",
  idempotency_key AS "idempotencyKey",
  source_checksum AS "sourceChecksum",
  source_uri AS "sourceUri",
  source_size_bytes::text AS "sourceSizeBytes",
  state::text AS state,
  item_count AS "itemCount",
  superseded_by::text AS "supersededBy",
  created_at AS "createdAt",
  updated_at AS "updatedAt"
`;

const batchItemSelection = `
  batch_item_id::text AS "batchItemId",
  batch_id::text AS "batchId",
  ordinal,
  innings_id::text AS "inningsId",
  over_number AS "overNumber",
  position_in_over AS "positionInOver",
  payload,
  state::text AS state,
  rejection_code AS "rejectionCode",
  rejection_detail AS "rejectionDetail",
  published_event_id::text AS "publishedEventId"
`;

const checkpointSelection = `
  batch_id::text AS "batchId",
  phase::text AS phase,
  last_ordinal AS "lastOrdinal",
  lease_owner AS "leaseOwner",
  lease_expires_at AS "leaseExpiresAt",
  attempt_count AS "attemptCount"
`;

function mapBatch(row: BatchRow): BatchRecord {
  const source =
    row.sourceChecksum && row.sourceUri && row.sourceSizeBytes
      ? {
          checksum: row.sourceChecksum,
          uri: row.sourceUri,
          sizeBytes: Number(row.sourceSizeBytes),
        }
      : null;

  return {
    batchId: row.batchId,
    submitterId: row.submitterId,
    competitionId: row.competitionId,
    idempotencyKey: row.idempotencyKey,
    source,
    state: row.state,
    itemCount: row.itemCount,
    supersededBy: row.supersededBy,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

function mapCheckpoint(row: BatchCheckpointRow): BatchCheckpointRecord {
  return {
    ...row,
    leaseExpiresAt: row.leaseExpiresAt?.toISOString() ?? null,
  };
}

function requireRow<Row>(row: Row | undefined, operation: string): Row {
  if (!row) {
    throw new Error(`${operation} returned no record`);
  }

  return row;
}

export function createBatchRepository(executor?: QueryExecutor): BatchRepository {
  function database(): QueryExecutor {
    return executor ?? getDatabasePool();
  }

  async function findBatch(where: string, values: unknown[]): Promise<BatchRecord | null> {
    const result = await executeQuery<BatchRow>(
      database(),
      `SELECT ${batchSelection} FROM batch WHERE ${where}`,
      values,
    );

    return result.rows[0] ? mapBatch(result.rows[0]) : null;
  }

  return {
    async createBatch(input) {
      const result = await executeQuery<BatchRow>(
        database(),
        `
          INSERT INTO batch (
            submitter_id,
            competition_id,
            idempotency_key,
            source_checksum,
            source_uri,
            source_size_bytes,
            state
          )
          VALUES ($1, $2, $3, $4, $5, $6, $7)
          RETURNING ${batchSelection}
        `,
        [
          input.submitterId,
          input.competitionId,
          input.idempotencyKey,
          input.source?.checksum ?? null,
          input.source?.uri ?? null,
          input.source?.sizeBytes ?? null,
          input.state ?? 'received',
        ],
      );

      return mapBatch(requireRow(result.rows[0], 'Batch insertion'));
    },

    findBatchById(batchId) {
      return findBatch('batch_id = $1::bigint', [batchId]);
    },

    findBatchByIdempotencyKey(submitterId, idempotencyKey) {
      return findBatch('submitter_id = $1::bigint AND idempotency_key = $2', [
        submitterId,
        idempotencyKey,
      ]);
    },

    async insertBatchItems(batchId, items) {
      if (items.length === 0) {
        return [];
      }

      const values: unknown[] = [batchId];
      const tuples = items.map((item) => {
        const first = values.length + 1;
        values.push(
          item.ordinal,
          item.inningsId,
          item.overNumber,
          item.positionInOver,
          JSON.stringify(item.payload),
          item.state ?? 'pending',
          item.rejectionCode ?? null,
          item.rejectionDetail === undefined || item.rejectionDetail === null
            ? null
            : JSON.stringify(item.rejectionDetail),
          item.publishedEventId ?? null,
        );

        return `(
          $1::bigint,
          $${first}::integer,
          $${first + 1}::bigint,
          $${first + 2}::smallint,
          $${first + 3}::smallint,
          $${first + 4}::jsonb,
          $${first + 5}::batch_item_state,
          $${first + 6}::text,
          $${first + 7}::jsonb,
          $${first + 8}::bigint
        )`;
      });

      const result = await executeQuery<BatchItemRecord>(
        database(),
        `
          INSERT INTO batch_item (
            batch_id,
            ordinal,
            innings_id,
            over_number,
            position_in_over,
            payload,
            state,
            rejection_code,
            rejection_detail,
            published_event_id
          )
          VALUES ${tuples.join(',')}
          RETURNING ${batchItemSelection}
        `,
        values,
      );

      return result.rows.sort((left, right) => left.ordinal - right.ordinal);
    },

    async listBatchItems(batchId, options) {
      const result = await executeQuery<BatchItemRecord>(
        database(),
        `
          SELECT ${batchItemSelection}
          FROM batch_item
          WHERE batch_id = $1::bigint
            AND ordinal > $2::integer
          ORDER BY ordinal ASC
          LIMIT $3::integer
        `,
        [batchId, options.afterOrdinal ?? -1, options.limit],
      );

      return result.rows;
    },

    async findCheckpoint(batchId) {
      const result = await executeQuery<BatchCheckpointRow>(
        database(),
        `SELECT ${checkpointSelection} FROM batch_checkpoint WHERE batch_id = $1::bigint`,
        [batchId],
      );

      return result.rows[0] ? mapCheckpoint(result.rows[0]) : null;
    },

    async upsertCheckpoint(input) {
      const result = await executeQuery<BatchCheckpointRow>(
        database(),
        `
          INSERT INTO batch_checkpoint (
            batch_id,
            phase,
            last_ordinal,
            lease_owner,
            lease_expires_at,
            attempt_count
          )
          VALUES ($1, $2, $3, $4, $5, $6)
          ON CONFLICT (batch_id) DO UPDATE SET
            phase = EXCLUDED.phase,
            last_ordinal = EXCLUDED.last_ordinal,
            lease_owner = EXCLUDED.lease_owner,
            lease_expires_at = EXCLUDED.lease_expires_at,
            attempt_count = EXCLUDED.attempt_count
          RETURNING ${checkpointSelection}
        `,
        [
          input.batchId,
          input.phase,
          input.lastOrdinal,
          input.leaseOwner ?? null,
          input.leaseExpiresAt ?? null,
          input.attemptCount,
        ],
      );

      return mapCheckpoint(requireRow(result.rows[0], 'Batch checkpoint upsert'));
