import type { Readable } from 'node:stream';

export interface StoredObjectVersion {
  versionId: string | null;
}

/** Provider boundary. It deliberately exposes neither URLs nor credentials. */
export interface ObjectStore {
  write(storageKey: string, source: Readable): Promise<StoredObjectVersion>;
  read(storageKey: string): Promise<Readable>;
  delete(storageKey: string): Promise<void>;
}

export class ObjectStorageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ObjectStorageError';
  }
}

export class ObjectSizeLimitError extends ObjectStorageError {
  readonly limitBytes: number;

  constructor(limitBytes: number) {
    super(`Object exceeds the ${limitBytes}-byte limit.`);
    this.name = 'ObjectSizeLimitError';
    this.limitBytes = limitBytes;
  }
}

export class StoredObjectAccessDeniedError extends ObjectStorageError {
  constructor() {
    super('Access to the stored object is denied.');
    this.name = 'StoredObjectAccessDeniedError';
  }
}

export class StoredObjectUnavailableError extends ObjectStorageError {
  constructor() {
    super('The stored object bytes are unavailable.');
    this.name = 'StoredObjectUnavailableError';
  }
}

import { Readable } from 'node:stream';

import { ObjectStorageError, type ObjectStore } from './object-store';

/** Test fake with deterministic failure hooks; never use it for production payloads. */
export class FakeObjectStore implements ObjectStore {
  private readonly objects = new Map<string, Buffer>();
  readonly deletedKeys: string[] = [];
  failNextWrite = false;
  failNextRead = false;
  failNextDelete = false;

  async write(storageKey: string, source: Readable) {
    if (this.failNextWrite) {
      this.failNextWrite = false;
      throw new ObjectStorageError('Fake object write failed.');
    }

    if (this.objects.has(storageKey)) {
      throw new ObjectStorageError('The fake object key already exists.');
    }

    const chunks: Buffer[] = [];
    for await (const chunk of source) {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    }
    this.objects.set(storageKey, Buffer.concat(chunks));
    return { versionId: null };
  }

  async read(storageKey: string): Promise<Readable> {
    if (this.failNextRead) {
      this.failNextRead = false;
      throw new ObjectStorageError('Fake object read failed.');
    }

    const object = this.objects.get(storageKey);
    if (!object) {
      throw new ObjectStorageError('The fake object does not exist.');
    }

    return Readable.from(object);
  }

  async delete(storageKey: string): Promise<void> {
    this.deletedKeys.push(storageKey);
    if (this.failNextDelete) {
      this.failNextDelete = false;
      throw new ObjectStorageError('Fake object deletion failed.');
    }
    this.objects.delete(storageKey);
  }

  has(storageKey: string): boolean {
    return this.objects.has(storageKey);
  }
}

import type { ContainerClient } from '@azure/storage-blob';
import type { Readable } from 'node:stream';

import { ObjectStorageError, type ObjectStore } from './object-store';

const AZURE_UPLOAD_BUFFER_BYTES = 4 * 1024 * 1024;
const AZURE_UPLOAD_CONCURRENCY = 4;

/** Production adapter for an already-provisioned private Azure Blob container. */
export class AzureBlobObjectStore implements ObjectStore {
  constructor(private readonly container: ContainerClient) {}

  async write(storageKey: string, source: Readable) {
    const blob = this.container.getBlockBlobClient(storageKey);
    const response = await blob.uploadStream(
      source,
      AZURE_UPLOAD_BUFFER_BYTES,
      AZURE_UPLOAD_CONCURRENCY,
      { conditions: { ifNoneMatch: '*' } },
    );

    return { versionId: response.versionId ?? null };
  }

  async read(storageKey: string): Promise<Readable> {
    const response = await this.container.getBlockBlobClient(storageKey).download();
    if (!response.readableStreamBody) {
      throw new ObjectStorageError('Azure Blob Storage returned no readable object body.');
    }

    return response.readableStreamBody;
  }

  async delete(storageKey: string): Promise<void> {
    await this.container
      .getBlockBlobClient(storageKey)
      .deleteIfExists({ deleteSnapshots: 'include' });
  }
}

import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

export type StoredObjectRetentionState =
  | 'retained'
  | 'deletion_pending'
  | 'expired'
  | 'deletion_failed';

export interface StoredObjectRecord {
  objectId: string;
  ownerId: string;
  originalFilename: string;
  mediaType: string;
  byteSize: number;
  sha256: string;
  storageKey: string;
  providerVersionId: string | null;
  retentionState: StoredObjectRetentionState;
  retentionExpiresAt: string;
  createdAt: string;
  deletedAt: string | null;
}

export interface CreateStoredObjectInput {
  objectId: string;
  ownerId: string;
  originalFilename: string;
  mediaType: string;
  byteSize: number;
  sha256: string;
  storageKey: string;
  providerVersionId: string | null;
  retentionExpiresAt: string;
}

export interface StoredObjectRepository {
  create(input: CreateStoredObjectInput): Promise<StoredObjectRecord>;
  findById(objectId: string): Promise<StoredObjectRecord | null>;
  updateRetentionState(
    objectId: string,
    state: StoredObjectRetentionState,
    deletedAt?: string | null,
  ): Promise<StoredObjectRecord>;
}

interface StoredObjectRow {
  objectId: string;
  ownerId: string;
  originalFilename: string;
  mediaType: string;
  byteSize: string;
  sha256: string;
  storageKey: string;
  providerVersionId: string | null;
  retentionState: StoredObjectRetentionState;
  retentionExpiresAt: Date;
  createdAt: Date;
  deletedAt: Date | null;
}

const selection = `
  object_id::text AS "objectId",
  owner_id::text AS "ownerId",
  original_filename AS "originalFilename",
  media_type AS "mediaType",
  byte_size::text AS "byteSize",
  sha256,
  storage_key AS "storageKey",
  provider_version_id AS "providerVersionId",
  retention_state::text AS "retentionState",
  retention_expires_at AS "retentionExpiresAt",
  created_at AS "createdAt",
  deleted_at AS "deletedAt"
`;

function mapStoredObject(row: StoredObjectRow): StoredObjectRecord {
  return {
    ...row,
    byteSize: Number(row.byteSize),
    retentionExpiresAt: row.retentionExpiresAt.toISOString(),
    createdAt: row.createdAt.toISOString(),
    deletedAt: row.deletedAt?.toISOString() ?? null,
  };
}

function requireRow(row: StoredObjectRow | undefined): StoredObjectRecord {
  if (!row) {
    throw new Error('Stored-object operation returned no record');
  }
  return mapStoredObject(row);
}

export function createStoredObjectRepository(
  executor?: QueryExecutor,
): StoredObjectRepository {
  const database = () => executor ?? getDatabasePool();

  return {
    async create(input) {
      const result = await executeQuery<StoredObjectRow>(
        database(),
        `
          INSERT INTO stored_object (
            object_id, owner_id, original_filename, media_type, byte_size,
            sha256, storage_key, provider_version_id, retention_expires_at
          )
          VALUES ($1::uuid, $2::bigint, $3, $4, $5, $6, $7, $8, $9::timestamptz)
          RETURNING ${selection}
        `,
        [
          input.objectId,
          input.ownerId,
          input.originalFilename,
          input.mediaType,
          input.byteSize,
          input.sha256,
          input.storageKey,
          input.providerVersionId,
          input.retentionExpiresAt,
        ],
      );
      return requireRow(result.rows[0]);
    },

    async findById(objectId) {
      const result = await executeQuery<StoredObjectRow>(
        database(),
        `SELECT ${selection} FROM stored_object WHERE object_id = $1::uuid`,
        [objectId],
      );
      return result.rows[0] ? mapStoredObject(result.rows[0]) : null;
    },

    async updateRetentionState(objectId, state, deletedAt = null) {
      const result = await executeQuery<StoredObjectRow>(
        database(),
        `
          UPDATE stored_object
          SET retention_state = $2::stored_object_retention_state,
              deleted_at = $3::timestamptz
          WHERE object_id = $1::uuid
          RETURNING ${selection}
        `,
        [objectId, state, deletedAt],
      );
      return requireRow(result.rows[0]);
    },
  };
}

